import Model from 'flarum/common/Model';
export default class Creative extends Model {
  name = (() => Model.attribute('name'))();
  type = (() => Model.attribute('type'))();
  status = (() => Model.attribute('status'))();
  weight = (() => Model.attribute('weight'))();
  destinationUrl = (() => Model.attribute('destinationUrl'))();
  labelOverride = (() => Model.attribute('labelOverride'))();
  variantGroup = (() => Model.attribute('variantGroup'))();
  payload = (() => Model.attribute('payload'))();

  /**
   * Placement key to weight. A null weight means "use the creative's own".
   */
  placements = (() => Model.attribute('placements'))();
  impressions = (() => Model.attribute('impressions'))();
  viewableImpressions = (() => Model.attribute('viewableImpressions'))();
  clicks = (() => Model.attribute('clicks'))();

  /**
   * Why a creative was rejected. Written by whoever rejected it and shown to
   * whoever submitted it: a rejection with no reason is one somebody resubmits
   * unchanged.
   */
  reviewReason = (() => Model.attribute('reviewReason'))();
  reviewedAt = (() => Model.attribute('reviewedAt', Model.transformDate))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  campaign = (() => Model.hasOne('campaign'))();
  reviewer = (() => Model.hasOne('reviewer'))();
}
flarum.reg.add('datlechin-placements', 'admin/models/Creative', Creative);