import app from 'flarum/common/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
/**
 * An address, and a way to get one without leaving the page.
 *
 * The address stays editable, because plenty of creatives point at an
 * advertiser's own CDN and always will; the upload is for the case where
 * somebody has a file and nowhere to put it. Before this existed, that case
 * had no answer at all, and it is the case a member submitting an advert is
 * always in.
 */
export default class ImageUploadField extends Component {
  uploading = false;
  error = null;
  view() {
    return m("div", {
      className: "ImageUploadField"
    }, m("div", {
      className: "ImageUploadField-row"
    }, m("input", {
      className: "FormControl",
      type: "url",
      value: this.attrs.value,
      placeholder: this.attrs.placeholder ?? 'https://',
      required: this.attrs.required,
      oninput: e => this.attrs.onchange(e.target.value)
    }), m("label", {
      className: "Button ImageUploadField-choose"
    }, this.uploading ? m(LoadingIndicator, {
      display: "inline",
      size: "small"
    }) : app.translator.trans('datlechin-placements.lib.upload'), m("input", {
      type: "file",
      accept: "image/jpeg,image/png,image/gif,image/webp",
      disabled: this.uploading,
      onchange: e => this.choose(e)
    })), this.attrs.value && m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-times",
      type: "button",
      title: app.translator.trans('datlechin-placements.lib.clear'),
      onclick: () => this.attrs.onchange('')
    })), this.error && m("div", {
      className: "ImageUploadField-error"
    }, this.error), this.attrs.value && m("img", {
      className: "ImageUploadField-preview",
      src: this.attrs.value,
      alt: "",
      onerror: this.hide,
      onload: this.show
    }));
  }
  hide(e) {
    e.target.style.display = 'none';
  }
  show(e) {
    e.target.style.display = '';
  }
  choose(e) {
    const input = e.target;
    const file = input.files?.[0];
    if (!file) return;
    const body = new FormData();
    body.append('image', file);
    this.uploading = true;
    this.error = null;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/placements/uploads`,
      body,
      // Without this, Mithril JSON-encodes the body and the multipart
      // boundary never happens, so the server sees no file at all.
      serialize: raw => raw
    }).then(response => {
      this.attrs.onchange(response.url);
    }).catch(error => {
      // The message the server gave, which says which rule was broken --
      // "must be an image", "may not be greater than 2048 kilobytes" -- and
      // is the only useful thing to show here.
      this.error = error?.response?.errors?.[0]?.detail ?? app.translator.trans('datlechin-placements.lib.upload_failed');
    }).finally(() => {
      this.uploading = false;
      // The same file can then be chosen again, which otherwise fires no
      // change event and looks like the button stopped working.
      input.value = '';
      m.redraw();
    });
  }
}
flarum.reg.add('datlechin-placements', 'common/components/ImageUploadField', ImageUploadField);